-- Catalogue Middle-earth relevé sur Warhammer.com France le 2026-11-05.
-- 290 produits répartis dans les six catégories officielles; 1 décor neutre conservé à part.
-- Les chevauchements entre filtres officiels ont été résolus en faveur de la catégorie la plus spécifique.
-- Noms français conservés lorsqu’ils sont proposés; descriptions laissées vides si indisponibles.
-- Images et liens vers Warhammer.com. IDs stables; script réexécutable sans effacer les descriptions ajoutées.
on conflict (id) do update set
  universe=excluded.universe, faction=excluded.faction, name=excluded.name,
  description=case when excluded.description <> '' then excluded.description else catalog_items.description end,
  price_eur=excluded.price_eur, image_url=excluded.image_url, product_url=excluded.product_url,
  price_source=excluded.price_source, price_checked_at=excluded.price_checked_at;
